"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[11575],{3331:(e,i,o)=>{o.d(i,{R:()=>r,x:()=>l});var n=o(36672);const a={},t=n.createContext(a);function r(e){const i=n.useContext(t);return n.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function l(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),n.createElement(t.Provider,{value:i},e.children)}},6554:(e,i,o)=>{o.r(i),o.d(i,{assets:()=>s,contentTitle:()=>l,default:()=>u,frontMatter:()=>r,metadata:()=>n,toc:()=>c});const n=JSON.parse('{"id":"2023/04/16","title":"2023-04-16","description":"Valve restringe gli account di 2500 utenti che hanno contrassegnato una recensione negativa di un gioco come utile","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/2023/04/16.md","sourceDirName":"2023/04","slug":"/2023/04/16","permalink":"/it/2023/04/16","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/it/docusaurus-plugin-content-docs//current/2023/04/16.md","tags":[],"version":"current","frontMatter":{"localized_date":"16 aprile 2023","top_news":"Valve restringe gli account di 2500 utenti che hanno contrassegnato una recensione negativa di un gioco come utile"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-17","permalink":"/it/2023/04/17"},"next":{"title":"2023-04-15","permalink":"/it/2023/04/15"}}');var a=o(23420),t=o(3331);const r={localized_date:"16 aprile 2023",top_news:"Valve restringe gli account di 2500 utenti che hanno contrassegnato una recensione negativa di un gioco come utile"},l="2023-04-16",s={},c=[{value:"Valve restringe gli account di 2500 utenti che hanno contrassegnato una recensione negativa di un gioco come utile",id:"valve-restringe-gli-account-di-2500-utenti-che-hanno-contrassegnato-una-recensione-negativa-di-un-gioco-come-utile",level:2},{value:"Perch\xe9 un panino al tacchino avvolto nella plastica costa 15 dollari all&#39;aeroporto di New York?",id:"perch\xe9-un-panino-al-tacchino-avvolto-nella-plastica-costa-15-dollari-allaeroporto-di-new-york",level:2},{value:"Controllo del traffico aereo Lofi - LAX",id:"controllo-del-traffico-aereo-lofi---lax",level:2},{value:"Cosa sono e come funzionano i modelli di trasformatori?",id:"cosa-sono-e-come-funzionano-i-modelli-di-trasformatori",level:2},{value:"Fondamenti di WebGPU",id:"fondamenti-di-webgpu",level:2},{value:"CEO di Google: &quot;possiamo cambiare l&#39;impostazione di questo gruppo in history-off&quot; [pdf]",id:"ceo-di-google-possiamo-cambiare-limpostazione-di-questo-gruppo-in-history-off-pdf",level:2},{value:"Sopravvivere al burnout (2015)",id:"sopravvivere-al-burnout-2015",level:2},{value:"Lo sviluppo di software a basso codice \xe8 una bugia",id:"lo-sviluppo-di-software-a-basso-codice-\xe8-una-bugia",level:2},{value:"Vulnerabilit\xe0 di esecuzione di codice remoto in Google che non sono disposti a correggere",id:"vulnerabilit\xe0-di-esecuzione-di-codice-remoto-in-google-che-non-sono-disposti-a-correggere",level:2},{value:"Sviluppo di Hypervisor in Rust",id:"sviluppo-di-hypervisor-in-rust",level:2}];function d(e){const i={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,t.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(i.header,{children:(0,a.jsx)(i.h1,{id:"2023-04-16",children:"2023-04-16"})}),"\n",(0,a.jsx)(i.h2,{id:"valve-restringe-gli-account-di-2500-utenti-che-hanno-contrassegnato-una-recensione-negativa-di-un-gioco-come-utile",children:"Valve restringe gli account di 2500 utenti che hanno contrassegnato una recensione negativa di un gioco come utile"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"https://tech.slashdot.org/story/23/04/14/175246/valve-restricts-accounts-of-2500-users-who-marked-a-negative-game-review-useful",children:"Originale"}),'.\nValve ha ristretto gli account di 2.500 utenti che hanno giudicato utile una recensione negativa di Warlander, con un conseguente divieto di 30 giorni di up e downvoting per gli interessati. I moderatori di Steam hanno classificato la recensione come "tentativo di truffa ai danni degli utenti o altre violazioni delle regole e delle linee guida di Steam", con la conseguente rimozione della recensione e la convinzione di molti che il sistema di recensioni sia "completamente inutile" a causa dell\'impatto delle azioni di Valve.']}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35577895",children:"Discussion Service"}),".\nValve limita gli account degli utenti che hanno segnato come utile una recensione negativa di un gioco, provocando le critiche degli utenti di Hacker News sul fatto che Valve permetta l'uso di \"software dannoso\" sulla sua piattaforma. Alcuni suggeriscono alternative al software anti-cheat, mentre altri sostengono che sia necessario per prevenire gli imbrogli nei giochi online. Nei commenti si discute dell'etica del monopolio di Steam sulla distribuzione dei videogiochi per PC, con opinioni diverse sulla necessit\xe0 dei monopoli e sull'efficacia del software anti-cheat."]}),"\n",(0,a.jsx)(i.h2,{id:"perch\xe9-un-panino-al-tacchino-avvolto-nella-plastica-costa-15-dollari-allaeroporto-di-new-york",children:"Perch\xe9 un panino al tacchino avvolto nella plastica costa 15 dollari all'aeroporto di New York?"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"https://hellgatenyc.com/why-is-airport-turkey-sandwich-expensive",children:"Originale"}),".\nN/A."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35580847",children:"Discussion Service"}),".\nGli utenti di Discussion Service discutono le ragioni per cui un panino al tacchino avvolto nella plastica costa 15 dollari negli aeroporti di New York; la concorrenza limitata all'interno degli aeroporti e la mancanza di termini di paragone per i venditori di F&B rendono impossibile garantire prezzi equi. Gli utenti suggeriscono ai passeggeri di portarsi i pasti da casa."]}),"\n",(0,a.jsx)(i.h2,{id:"controllo-del-traffico-aereo-lofi---lax",children:"Controllo del traffico aereo Lofi - LAX"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"https://www.lofiatc.com/?icao=KLAX",children:"Originale"}),".\nIl post condivide la frequenza della torre di Los Angeles (Nord) di KLAX, che \xe8 133.900. Il post include un video musicale di Glimlip x Yasper e fornisce un'opzione per il feedback o la donazione."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35583228",children:"Discussion Service"}),".\nGli utenti di Hacker News stanno discutendo di lofiatc.com, una nuova applicazione web che combina la musica d'ambiente con le comunicazioni del controllo del traffico aereo in modo rilassante, suscitando interesse; alcuni utenti chiedono di aggiungere altre funzioni e le comunicazioni radio. Gli utenti condividono anche le loro preferenze per la musica d'ambiente durante il lavoro, consigliando SomaFM e mynoise.net, e alcuni suggeriscono il black metal come alternativa adatta, anche se non c'\xe8 un chiaro consenso sul tipo di musica d'ambiente migliore per la concentrazione."]}),"\n",(0,a.jsx)(i.h2,{id:"cosa-sono-e-come-funzionano-i-modelli-di-trasformatori",children:"Cosa sono e come funzionano i modelli di trasformatori?"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"https://txt.cohere.ai/what-are-transformer-models/",children:"Originale"}),".\nI modelli trasformatori sono un nuovo sviluppo dell'apprendimento automatico e sono in grado di generare testi coerenti tenendo conto del contesto. In grado di svolgere diversi compiti, come la traduzione tra le lingue e la risposta alle domande, i trasformatori sono costituiti da vari componenti, tra cui la tokenizzazione, l'incorporazione, la codifica posizionale, i blocchi trasformatori e il softmax. Il blocco trasformatore pi\xf9 complesso impiega componenti di attenzione e di feedforward, con l'attenzione a pi\xf9 teste utilizzata per modificare i vettori e fornire un maggiore contesto. Il post-training insegna ai trasformatori a svolgere compiti specifici e la loro capacit\xe0 di catturare il contesto ne ha determinato il successo."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35576918",children:"Discussion Service"}),".\nGli utenti discutono dei modelli di trasformatori, mettendo in dubbio la loro efficacia e la completezza dei contenuti promozionali. Vengono citati metodi alternativi per la tokenizzazione e vengono consigliate risorse per saperne di pi\xf9, tra cui corsi, video e documenti. Il comportamento emergente mostrato da modelli semplici nell'intelligenza artificiale e la connessione tra dettagli computazionali e comportamento di alto livello sono esplorati, evidenziando un'area di studio attiva chiamata interpretabilit\xe0 meccanicistica."]}),"\n",(0,a.jsx)(i.h2,{id:"fondamenti-di-webgpu",children:"Fondamenti di WebGPU"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"https://webgpufundamentals.org/",children:"Originale"}),".\nQuesto post fornisce una serie di articoli per imparare i fondamenti della WebGPU, tra cui il layout della memoria dati, la matematica 3D e la WebGPU da WebGL. Il post include anche risorse e riferimenti per ulteriori approfondimenti, oltre a opportunit\xe0 di contributo. Si ringrazia jrprice per il suo contributo."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35579334",children:"Discussion Service"}),".\nWebGPU Fundamentals guadagna attenzione su Hacker News come successore di WebGL per la grafica sui browser web. Gli utenti discutono delle potenziali applicazioni per la simulazione, l'apprendimento profondo e le preoccupazioni per la diffusione delle funzionalit\xe0 dei browser. I commenti riguardano anche i sequencer MIDI basati sul web, gli strumenti sperimentali e WebUSB per gli aggiornamenti del firmware. Alcuni sostengono i vantaggi degli strumenti basati sul web, mentre altri esprimono preoccupazione per i rischi di sicurezza e i problemi di compatibilit\xe0. WebGPU non \xe8 pensato per essere di alto livello o accessibile ai principianti, ma un'API GPU di basso livello per utenti esperti."]}),"\n",(0,a.jsx)(i.h2,{id:"ceo-di-google-possiamo-cambiare-limpostazione-di-questo-gruppo-in-history-off-pdf",children:'CEO di Google: "possiamo cambiare l\'impostazione di questo gruppo in history-off" [pdf]'}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"https://ia601707.us.archive.org/28/items/gov.uscourts.cand.364454/gov.uscourts.cand.364454.385.0.pdf",children:"Originale"}),".\nHacker News sta discutendo di WebGPU Fundamentals, il successore di WebGL, per il suo potenziale nel deep learning lato client e nelle simulazioni via browser. Le conversazioni toccano anche il tema delle funzionalit\xe0 del browser, la sua potenziale utilit\xe0 e convenienza e la portata dei browser come applicazioni o visualizzatori. Inoltre, gli utenti discutono di come renderizzare il testo utilizzando WebGPU, della sua compatibilit\xe0 con i progetti di intelligenza artificiale e della collaborazione in corso tra i team WebGPU."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35585174",children:"Discussion Service"}),".\nL'amministratore delegato di Google Sundar Pichai \xe8 accusato di aver richiesto una modifica delle impostazioni dei gruppi di Google Chat per \"disattivare la cronologia\", nonostante le potenziali implicazioni legali e la violazione dell'FRCP 37(e). Gli utenti di Discussion Service discutono dell'importanza di preservare le registrazioni scopribili e delle preoccupazioni sulla legalit\xe0 delle pratiche di cancellazione automatica, con esempi di altre comunicazioni elettroniche che cancellano i messaggi. Inoltre, vengono condivise discussioni sulla conservazione dei dati, sulle normative governative e sui monopoli a livello mondiale, mentre emergono preoccupazioni sull'attivit\xe0 Android di Google e sulla sua mancanza di concorrenza."]}),"\n",(0,a.jsx)(i.h2,{id:"sopravvivere-al-burnout-2015",children:"Sopravvivere al burnout (2015)"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"https://lifeofaudrey.com/essays/surviving_burnout.html",children:"Originale"}),".\nIl burnout nell'industria tecnologica \xe8 causato da un disallineamento di responsabilit\xe0, autorit\xe0 e risorse. L'esperienza dell'autrice con il burnout l'ha spinta a lasciare il suo lavoro e ad entrare in un periodo di recupero, che l'ha portata ad avviare la sua attivit\xe0. Il burnout \xe8 un problema strutturale che richiede soluzioni strutturali, con supporto e fondi per il recupero delle persone colpite."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35577285",children:"Discussion Service"}),".\nUn articolo su Hacker News parla dell'importanza di trovare un equilibrio per evitare il burnout e mantenere la salute mentale e fisica, mentre gli utenti condividono esperienze personali e offrono consigli. Alcuni utenti di Discussion Service sottolineano le differenze tra depressione e burnout, mentre altri offrono consigli per affrontare i luoghi di lavoro che inducono il burnout o per avviare un'attivit\xe0 come potenziale soluzione. Diversi lettori discutono anche dell'efficacia di un lifestyle coach o di un terapeuta per combattere il burnout dei dipendenti, con opinioni contrastanti. In definitiva, la conclusione principale \xe8 che l'interesse per il lavoro \xe8 importante, ma non a scapito del proprio benessere."]}),"\n",(0,a.jsx)(i.h2,{id:"lo-sviluppo-di-software-a-basso-codice-\xe8-una-bugia",children:"Lo sviluppo di software a basso codice \xe8 una bugia"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"https://jaylittle.com/post/view/2023/4/low-code-software-development-is-a-lie",children:"Originale"}),".\nUn esperto sviluppatore di software sostiene che la creazione di software \xe8 difficile perch\xe9 i clienti e gli sviluppatori non capiscono le cause dei problemi che vogliono risolvere, piuttosto che per colpa dei linguaggi e degli strumenti di codifica. L'autore critica l'idea di strumenti \"a basso codice\" come OutSystems, affermando che non eliminano la complessit\xe0 intrinseca e possono portare a sistemi software mal concepiti, oltre a essere costosi e a comportare il vendor lock-in. Progettare correttamente una soluzione \xe8 la parte pi\xf9 difficile del processo di sviluppo del software e nessuno strumento pu\xf2 sostituire la riflessione, la discussione e la pianificazione necessarie."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35578240",children:"Discussion Service"}),".\nLo sviluppo di software low-code \xe8 utile per i problemi pi\xf9 semplici, ma non \xe8 adatto per quelli complessi e non dovrebbe sostituire del tutto gli sviluppatori. I commenti di Discussion Service discutono i limiti e i compromessi delle piattaforme low-code, tra cui la scarsa testabilit\xe0, il versioning e gli strumenti di debug che possono portare al vendor lock-in. Alcuni esperti suggeriscono che gli strumenti low-code possono essere utili per la prototipazione e per alcune applicazioni, ma altri mettono in guardia da un eccessivo affidamento su di essi e consigliano di selezionare attentamente gli strumenti appropriati. Sebbene il low-code abbia diversi casi d'uso, la definizione \xe8 confusa e potenzialmente fuorviante, con Excel e i grafici degli shader come esempi."]}),"\n",(0,a.jsx)(i.h2,{id:"vulnerabilit\xe0-di-esecuzione-di-codice-remoto-in-google-che-non-sono-disposti-a-correggere",children:"Vulnerabilit\xe0 di esecuzione di codice remoto in Google che non sono disposti a correggere"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"https://giraffesecurity.dev/posts/google-remote-code-execution/",children:"Originale"}),".\nUn ricercatore di sicurezza ha trovato una vulnerabilit\xe0 in Google che permetteva di eseguire codice arbitrario sui computer di oltre 50 dipendenti di Google, causata da una confusione di dipendenze nel sistema di gestione di Python. Google ha inizialmente classificato la vulnerabilit\xe0 come grave, ma in seguito l'ha modificata in comportamento previsto. Il ricercatore teme che la vulnerabilit\xe0 possa essere sfruttata, dal momento che ha ricevuto download quotidiani da parte dei dipendenti di Google, e sospetta che Google non comprenda il problema o non si preoccupi di risolverlo."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35581532",children:"Discussion Service"}),".\nUna vulnerabilit\xe0 RCE (Remote Code Execution) riscontrata nel software di Google non sarebbe stata risolta; alcuni utenti hanno fatto notare che il sistema di gestione dei pacchetti di Java ha un modo pi\xf9 sicuro di caricare i pacchetti rispetto al sistema di Rust, mentre altri suggeriscono che ",(0,a.jsx)(i.code,{children:"pip install --extra-index-url"})," ignora i registri specifici dell'utente, rendendo inutili i registri privati. Google ha adottato misure di sicurezza a fiducia zero per combattere le minacce interne, ma un APT potrebbe sfruttare questa vulnerabilit\xe0 per farsi strada nell'ambiente. Si sottolinea inoltre la necessit\xe0 di migliori soluzioni di gestione dei pacchetti e il ruolo dello zero-trust nella prevenzione di tali attacchi."]}),"\n",(0,a.jsx)(i.h2,{id:"sviluppo-di-hypervisor-in-rust",children:"Sviluppo di Hypervisor in Rust"}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"https://memn0ps.github.io/hypervisor-development-in-rust-part-1/",children:"Originale"}),".\nQuesto articolo descrive lo sviluppo di un hypervisor di ricerca basato su Rust per la virtualizzazione Intel VT-x, fornendo esempi di codice Rust per il funzionamento di VMX e discutendo il processo di inizializzazione delle regioni di memoria per le CPU virtuali. L'articolo vuole essere una risorsa utile per gli esperti nel campo della virtualizzazione con Rust. L'articolo mantiene la neutralit\xe0 e fornisce riferimenti e crediti."]}),"\n",(0,a.jsxs)(i.p,{children:[(0,a.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35579876",children:"Discussion Service"}),".\nUn utente di Hacker News commenta l'articolo sulla virtualizzazione della CPU ed esprime interesse per la virtualizzazione dei dispositivi, evidenziando le sfide affrontate e proponendo nuove soluzioni. Altri utenti forniscono risorse e alternative per gli utenti Linux interessati a questo campo."]})]})}function u(e={}){const{wrapper:i}={...(0,t.R)(),...e.components};return i?(0,a.jsx)(i,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}}}]);